import torch


def _rms_norm_into(x, weight, eps, y):
    y.copy_(torch.nn.functional.rms_norm(x.float(), (x.shape[-1],), weight.float(), eps))


_compiled = None


def run(x, weight, eps, y):
    global _compiled
    if _compiled is None:
        # dynamic=True matches Automodel, which compiles once for a varying token count.
        _compiled = torch.compile(_rms_norm_into, dynamic=True)
    _compiled(x, weight, eps, y)
